lessons.starter:
static boolean isPrime(int n) {
    return false;
}

lessons.solution:
static boolean isPrime(int n) {
    if(n<2)return false;
    for(int d=2;d<=n/d;d++) {
        if(n%d==0)return false;
    }
    return true;
}

static int factorial(int n) {
    if(n<=1)return 1;
    return n*factorial(n-1);
}
